UPDATE "Product" SET "shortDescription" = 'Spray solaire SPF 30 — protection moyenne à élevée UVA/UVB, extrait d''hamamélis, vitamine E, Aloe Vera et Panthénol, 150 ml. Gamme Aurodhea by Chogan.', "updatedAt" = NOW() WHERE "choganCode" = 'SOL01B' AND ("shortDescription" LIKE '%Produit Chogan, distribué au Sénégal par JAMAAL.' OR "shortDescription" LIKE '%Produit Chogan.');
UPDATE "Product" SET "longDescription" = ARRAY['Protection moyenne à élevée à large spectre, filtrant à la fois les rayons UVA et UVB. Contient de l''extrait d''hamamélis, utile contre les érythèmes solaires.', 'Enrichi en vitamine E, il exerce une action antioxydante et protège des dommages liés au photo-vieillissement, en évitant la formation de rides, de taches et de discromies diffuses. Enrichi en Aloe Vera et Panthénol, il laisse la peau douce et hydratée.', 'Texture fluide et légère en spray, facile à appliquer. Résistant à l''eau, sans alcool et ne laissant pas de traces.', 'Précautions : usage externe ; éviter le contact avec les yeux ; ne remplace pas une protection vestimentaire adaptée ni une exposition solaire raisonnée. Ne remplace pas un avis médical.']::text[], "updatedAt" = NOW() WHERE "choganCode" = 'SOL01B' AND (coalesce(cardinality("longDescription"), 0) = 0 OR (cardinality("longDescription") <= 2 AND (array_to_string("longDescription", ' ') LIKE '%distribué au Sénégal par JAMAAL%' OR array_to_string("longDescription", ' ') LIKE '%Produit officiel Chogan%')));
